BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='1s';
SET LOCAL search_path=pg_catalog;
SELECT jsonb_build_object(
 'transactionReadOnly',current_setting('transaction_read_only'),
 'searchPath',current_setting('search_path'),
 'databaseExpected',current_database()='knolstory_next_production',
 'roles',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'login',rolcanlogin,'superuser',rolsuper,'createDatabase',rolcreatedb,'createRole',rolcreaterole,'replication',rolreplication,'bypassRls',rolbypassrls) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('knolstory_next_app','knolstory_next_owner')),
 'appMembershipCount',(SELECT count(*) FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member WHERE r.rolname='knolstory_next_app'),
 'database',jsonb_build_object('ownerExpected',(SELECT pg_get_userbyid(datdba)='knolstory_next_owner' FROM pg_database WHERE datname=current_database()),'appConnect',has_database_privilege('knolstory_next_app',current_database(),'CONNECT'),'appCreate',has_database_privilege('knolstory_next_app',current_database(),'CREATE'),'appTemporary',has_database_privilege('knolstory_next_app',current_database(),'TEMPORARY'),'publicPrivileges',(SELECT COALESCE(jsonb_agg(a.privilege_type ORDER BY a.privilege_type),'[]') FROM pg_database d CROSS JOIN LATERAL aclexplode(COALESCE(d.datacl,acldefault('d',d.datdba)))a WHERE d.datname=current_database() AND a.grantee=0)),
 'schemas',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'appUsage',has_schema_privilege('knolstory_next_app',oid,'USAGE'),'appCreate',has_schema_privilege('knolstory_next_app',oid,'CREATE'),'ownedByApp',pg_get_userbyid(nspowner)='knolstory_next_app') ORDER BY nspname) FROM pg_namespace WHERE nspname IN ('public','knolstory_auth','knolstory_storage')),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'ownerExpected',pg_get_userbyid(c.relowner)='knolstory_next_owner','select',has_table_privilege('knolstory_next_app',c.oid,'SELECT'),'insert',has_table_privilege('knolstory_next_app',c.oid,'INSERT'),'update',has_table_privilege('knolstory_next_app',c.oid,'UPDATE'),'delete',has_table_privilege('knolstory_next_app',c.oid,'DELETE'),'truncate',has_table_privilege('knolstory_next_app',c.oid,'TRUNCATE'),'references',has_table_privilege('knolstory_next_app',c.oid,'REFERENCES'),'trigger',has_table_privilege('knolstory_next_app',c.oid,'TRIGGER'),'rowSecurity',c.relrowsecurity,'columnInsert',has_any_column_privilege('knolstory_next_app',c.oid,'INSERT'),'columnUpdate',has_any_column_privilege('knolstory_next_app',c.oid,'UPDATE'),'columnReferences',has_any_column_privilege('knolstory_next_app',c.oid,'REFERENCES')) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('knolstory_auth','knolstory_storage') AND c.relkind IN ('r','p')),
 'sequences',(SELECT COALESCE(jsonb_agg(jsonb_build_object('schema',n.nspname,'sequence',c.relname,'appUsage',has_sequence_privilege('knolstory_next_app',c.oid,'USAGE'),'appSelect',has_sequence_privilege('knolstory_next_app',c.oid,'SELECT'),'appUpdate',has_sequence_privilege('knolstory_next_app',c.oid,'UPDATE')) ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('knolstory_auth','knolstory_storage') AND c.relkind='S'),
 'applicationSecurityDefinerCount',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('knolstory_auth','knolstory_storage') AND p.prosecdef),
 'allUserSchemaCreateCount',(SELECT count(*) FROM pg_namespace WHERE nspname NOT LIKE 'pg_%' AND nspname<>'information_schema' AND has_schema_privilege('knolstory_next_app',oid,'CREATE')),
 'appOwnedSharedOrCurrentObjectCount',(SELECT count(*) FROM pg_shdepend WHERE refclassid='pg_authid'::regclass AND refobjid=(SELECT oid FROM pg_roles WHERE rolname='knolstory_next_app') AND deptype='o' AND dbid IN (0,(SELECT oid FROM pg_database WHERE datname=current_database()))),
 'appExecutableUserSecurityDefinerCount',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND p.prosecdef AND has_function_privilege('knolstory_next_app',p.oid,'EXECUTE')),
 'appOwnedApplicationFunctionCount',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('knolstory_auth','knolstory_storage') AND pg_get_userbyid(p.proowner)='knolstory_next_app')
);
COMMIT;
